namespace GeetaStudio.Api;

internal static class SocialPage
{
    internal const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Publishing workbench</title>
<style>body{font:16px system-ui;margin:2rem auto;max-width:1050px;padding:0 1rem;color:#173b32}fieldset,article{border:1px solid #bccfc5;border-radius:10px;margin:1rem 0;padding:1rem}label{display:block;margin:.5rem 0}input,select,textarea,button{font:inherit;padding:.5rem;max-width:100%;box-sizing:border-box}textarea{width:100%;min-height:90px}button{margin:.3rem;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere}#status{white-space:pre-wrap}a{color:#174e81}</style>
<h1>Publishing workbench</h1><p>Prepare and review destination packages, then schedule a local simulation or export for manual publishing. No live social account is connected. Fixture results are clearly labeled and never prove public release.</p>
<nav><a href="/staff/editorial">Editorial</a> · <a href="/staff/media">Media</a> · <a href="/staff/watch">WATCH</a></nav>
<fieldset><legend>Your workspace</legend><label>Tenant code <input id="tenant"></label><label>Universe code <input id="universe"></label><button id="load">Load workspace</button></fieldset><p id="status" role="status" aria-live="polite"></p>
<fieldset><legend>Destination account</legend><label>Platform <select id="platform"></select></label><label>Account name <input id="accountKey"></label><label>Platform account reference <input id="accountRef"></label><label>Version <input id="accountVersion" type="number" value="1" min="1"></label><label>Operation <select id="mode"><option>ExportOnly</option><option>Fixture</option></select></label><label>Fixture adapter <select id="adapter"><option>social.fixture.a.v1</option><option>social.fixture.b.v1</option><option>social.unknown.v1</option><option>social.rate-limit.v1</option></select></label><label>Binding evidence <input id="accountEvidence" placeholder="manual:your-account-reference or fixture:your-test"></label><button id="register">Register destination</button><p>Export-only accounts have no verified token or platform permissions. Credential renewal requires a new account version and future qualified authorization integration. Never paste tokens here.</p><div id="accounts"></div></fieldset>
<fieldset><legend>Prepare a package</legend><label>Destination <select id="account"></select></label><label>Approved editorial content <select id="content"></select></label><label>Format <select id="format"></select></label><label>Package name <input id="packageKey"></label><label>Campaign <input id="campaign"></label><label>Destination title (optional) <input id="title"></label><label>Caption (blank uses approved body) <textarea id="caption"></textarea></label><label>HTTPS link <input id="link"></label><label>Approved image/thumbnail version codes (comma separated) <input id="images"></label><label>Approved WATCH production code for video <input id="watch"></label><label>Video shape <select id="aspect"><option>Vertical</option><option>Standard</option></select></label><label><input id="kids" type="checkbox"> Intended for children</label><button id="prepare">Prepare for review</button></fieldset>
<fieldset><legend>Review and schedule</legend><label>Review type <select id="reviewMode"><option>Fixture</option><option>Manual</option></select></label><label>Review evidence <input id="reviewEvidence" placeholder="fixture:technical-check or manual:actual-review"></label><label>Schedule (your local time) <input id="when" type="datetime-local"></label><p id="zone"></p><div id="packages"></div></fieldset>
<h2>Publication history</h2><p>Unknown outcomes require reconciliation at their original provider and account. Withdrawal records intent; it does not claim that an external post was removed.</p><div id="publications"></div>
<details><summary>Record a callback or actual manual receipt</summary><label>Publication code <input id="receiptId"></label><label>Receipt details <textarea id="receipt" placeholder="Paste a SocialReceipt object using the exact platform, account, adapter, approved payload hash, event ID and real remote ID/URL."></textarea></label><button id="record">Record receipt</button></details>
<h2>Notifications</h2><p>Private in-app review/recovery notices; no email or external messages are sent.</p><div id="notifications"></div>
<script>
const el=id=>document.getElementById(id),uid=()=>crypto.randomUUID();let capabilities=[],accounts=[],packages=[],publications=[];
let base='';function message(x){el('status').textContent=x}async function call(path,body){let r=await fetch(base+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:body?JSON.stringify(body):undefined});if(!r.ok)throw new Error(await r.text());return r.status===204?null:await r.json()}
function button(parent,label,action){let b=document.createElement('button');b.textContent=label;b.onclick=()=>action().catch(e=>message(e.message));parent.append(b)}
function card(parent,text){let a=document.createElement('article');let p=document.createElement('p');p.textContent=text;a.append(p);parent.append(a);return a}
function options(id,items){el(id).replaceChildren();for(let [value,label] of items){let o=document.createElement('option');o.value=value;o.textContent=label;el(id).append(o)}}
async function refresh(){[accounts,packages,publications]=await Promise.all([call('/accounts'),call('/packages'),call('/publications')]);options('account',accounts.filter(x=>x.enabled).map(x=>[x.id,x.binding.platform+' · '+x.binding.key+' v'+x.binding.version+' · '+x.connectionState]));formats();el('accounts').replaceChildren();for(let a of accounts){let n=card(el('accounts'),a.binding.platform+' / '+a.binding.accountReference+' / '+a.connectionState+' / token: '+a.tokenState+' / qualified: '+a.qualified);for(let action of ['Disable','Revoke'])button(n,action,async()=>{await call('/accounts/'+a.id+'/control',{operationId:uid(),expectedRowVersion:a.rowVersion,action,evidenceReference:el('accountEvidence').value});await refresh()})}
el('packages').replaceChildren();for(let p of packages){let n=card(el('packages'),p.key+' · '+p.reviewStatus+' · '+(p.snapshot?.payload.platform??'withheld')+' · '+p.blocks.join(', '));if(p.snapshot){let preview=document.createElement('pre');let v=p.snapshot.payload;preview.textContent=v.title+'\n'+v.text+'\n'+v.article+'\n'+v.slides.join('\n')+'\n'+v.contentLabel+' · '+v.media.length+' media bindings';n.append(preview)}for(let decision of ['Approve','Reject','Withdraw'])button(n,decision,async()=>{await call('/packages/'+p.id+'/review',{operationId:uid(),expectedRowVersion:p.rowVersion,payloadHash:p.payloadHash,decision,mode:el('reviewMode').value,evidenceReference:el('reviewEvidence').value});await refresh()});button(n,'Download reviewed manifest',async()=>{let v=await call('/packages/'+p.id+'/export');let url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download=p.key+'.json';a.click();URL.revokeObjectURL(url)});button(n,'Schedule',async()=>{if(!el('when').value)throw new Error('Choose a schedule time.');await call('/publications',{operationId:uid(),packageId:p.id,scheduledUtc:new Date(el('when').value).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});await refresh()})}
el('publications').replaceChildren();for(let p of publications){let n=card(el('publications'),p.id+' · '+p.mode+' · '+p.platform+' / '+p.accountReference+' / '+p.adapter+' · '+p.state+' · '+(p.remoteUrl??'no external receipt')+' · '+(p.outcome??''));for(let action of ['Withdraw','Reconcile'])button(n,action,async()=>{await call('/publications/'+p.id+'/control',{operationId:uid(),expectedRowVersion:p.rowVersion,action,evidenceReference:el('reviewEvidence').value});await refresh()});let history=document.createElement('pre');history.textContent=p.history.map(x=>x.kind+': '+x.detail).join('\n');n.append(history)}
el('notifications').replaceChildren();for(let n of await call('/notifications')){let a=card(el('notifications'),n.kind+': '+n.detail+(n.acknowledged?' · acknowledged':''));if(!n.acknowledged)button(a,'Acknowledge',async()=>{await call('/notifications/'+n.id+'/ack',{operationId:uid(),expectedRowVersion:n.rowVersion,action:'Acknowledge',evidenceReference:'manual:staff-read'});await refresh()})}}
function formats(){let a=accounts.find(x=>x.id===el('account').value);let c=capabilities.find(x=>x.key===a?.binding.capabilityKey);options('format',(c?.formats??[]).map(x=>[x,x]))}el('account').onchange=formats;
el('load').onclick=async()=>{try{base='/api/v1/social/tenants/'+encodeURIComponent(el('tenant').value)+'/universes/'+encodeURIComponent(el('universe').value);capabilities=await call('/capabilities');options('platform',capabilities.map(x=>[x.platform,x.platform]));let r=await fetch('/api/v1/editorial/tenants/'+encodeURIComponent(el('tenant').value)+'/universes/'+encodeURIComponent(el('universe').value)+'/items',{credentials:'same-origin'});if(!r.ok)throw new Error('Unable to load editorial workspace.');let items=await r.json();options('content',items.filter(x=>['Approved','Scheduled','Published'].includes(x.state)).map(x=>[x.id,x.key+' · '+x.format]));await refresh();message('Workspace loaded. Live publishing remains unqualified.')}catch(e){message(e.message)}};
el('register').onclick=async()=>{try{let c=capabilities.find(x=>x.platform===el('platform').value);let fixture=el('mode').value==='Fixture';await call('/accounts',{operationId:uid(),key:el('accountKey').value,version:Number(el('accountVersion').value),platform:c.platform,accountReference:el('accountRef').value,adapter:fixture?el('adapter').value:'manual.export.v1',mode:el('mode').value,capabilityKey:c.key,authorizedScopes:fixture?c.requiredScopes:[],tokenExpiresUtc:null,evidenceReference:el('accountEvidence').value});await refresh()}catch(e){message(e.message)}};
el('prepare').onclick=async()=>{try{await call('/packages',{operationId:uid(),key:el('packageKey').value,editorialItemId:el('content').value,accountId:el('account').value,format:el('format').value,campaignId:el('campaign').value,caption:el('caption').value,link:el('link').value,imageVersionIds:el('images').value.split(',').map(x=>x.trim()).filter(Boolean),watchProductionId:el('watch').value||null,aspect:el('aspect').value,madeForKids:el('kids').checked,destinationTitle:el('title').value});await refresh()}catch(e){message(e.message)}};
el('record').onclick=async()=>{try{let r=JSON.parse(el('receipt').value);r.operationId=uid();await call('/publications/'+el('receiptId').value+'/receipt',r);await refresh()}catch(e){message(e.message)}};
el('zone').textContent='Timezone: '+Intl.DateTimeFormat().resolvedOptions().timeZone;
</script></html>
""";
}
